// Base64 embedded resume data for instant download without browser PDF viewer plugins
export const ROJINA_RESUME_B64 = "";

export function handleResumeDownload(e?: React.MouseEvent) {
  if (e) e.preventDefault();
  const filename = "Rojina_Duwal_QA_CV.pdf";

  function triggerBlobDownload(blob: Blob, name: string) {
    const blobUrl = window.URL.createObjectURL(blob);
    const tempLink = document.createElement("a");
    tempLink.style.display = "none";
    tempLink.href = blobUrl;
    tempLink.download = name;
    document.body.appendChild(tempLink);
    tempLink.click();
    setTimeout(() => {
      document.body.removeChild(tempLink);
      window.URL.revokeObjectURL(blobUrl);
    }, 1500);
  }

  function base64ToBlob(base64Data: string, contentType: string) {
    const byteCharacters = atob(base64Data);
    const byteArrays = [];
    const sliceSize = 1024;
    for (let offset = 0; offset < byteCharacters.length; offset += sliceSize) {
      const slice = byteCharacters.slice(offset, offset + sliceSize);
      const byteNumbers = new Array(slice.length);
      for (let i = 0; i < slice.length; i++) {
        byteNumbers[i] = slice.charCodeAt(i);
      }
      byteArrays.push(new Uint8Array(byteNumbers));
    }
    return new Blob(byteArrays, { type: contentType || "application/octet-stream" });
  }

  try {
    const blob = base64ToBlob(ROJINA_RESUME_B64, "application/octet-stream");
    triggerBlobDownload(blob, filename);
    return;
  } catch (err) {
    console.warn("Base64 blob conversion error, attempting fetch fallback:", err);
  }

  fetch("/assets/resume/Rojina_Duwal_QA_CV.pdf")
    .then((res) => {
      if (!res.ok) throw new Error("Fetch failed");
      return res.blob();
    })
    .then((pdfBlob) => {
      const forceDownloadBlob = new Blob([pdfBlob], { type: "application/octet-stream" });
      triggerBlobDownload(forceDownloadBlob, filename);
    })
    .catch(() => {
      const fallbackLink = document.createElement("a");
      fallbackLink.href = "/assets/resume/Rojina_Duwal_QA_CV.pdf";
      fallbackLink.download = filename;
      document.body.appendChild(fallbackLink);
      fallbackLink.click();
      document.body.removeChild(fallbackLink);
    });
}
